  [8688] = { nil, nil, nil, nil, "I cieli, con le loro stelle innumerevoli, custodiscono le risposte ai misteri della terra, {name}. Potranno allora i saggi, e i fortunati, alzare lo sguardo e trovare la verità?", nil, nil, nil, nil, 0x3da1f0cc, "mmmm." },
