  [8733] = { "Eranikus, il tiranno del sogno", "Vai sul continente di Teldrassil e trova l'agente di Malfurion da qualche parte fuori dalle mura di Darnassus.", "Questo è un viaggio di redenzione, eroe. Se oggi fossi ucciso, sarei morto per una causa giusta e retta. Devi recuperare il frammento verde dello scettro. Devi purificare Eranikus dalla corruzione che gli Old Gods gli hanno inflitto.\n\nVai a Darnassus. Appena fuori dalle mura della città troverai uno dei miei agenti. Questo agente metterà in moto le cose per noi e informerà Tyrande dei nostri piani senza allertare Staghelm.\n\n<Malfurion sospira.>\n\nUna caduta in disgrazia preparata in mille anni...", nil, "Il fuoco fatuo è silenzioso, a parte un ronzio sommesso. Stranamente, riesce a comunicare con te attraverso il pensiero.", 0xbe6d8014, 0x357b9a72, 0xd703f3de, nil, 0x9acaa65e, "...m." },
  [8734] = { "Tyrande e Remulos", "Vai a Moonglade e parla con Keeper Remulos.", "Tyrande sarà avvisata, mortale. Shan'do Stormrage mi ha preparato a questa eventualità.\n\nOra devi andare a Moonglade e parlare con Remulos. Ti darà altre istruzioni per l'evocazione di Eranikus.\n\nTutti ti auguriamo buona fortuna.", nil, "Sarebbe impossibile strappare Eranikus al sogno, se si rifiutasse. Le sue intenzioni, però, lo costringono a entrare nel nostro mondo. Vuole distruggere la manifestazione vivente di Malfurion. Riuscirci vorrebbe dire la fine di uno dei più potenti alleati del sogno. Se Malfurion cadesse, il Nightmare consumerebbe tutto ciò che resta...", 0x2bb57255, 0x90072af4, 0xad596e43, nil, 0xadfdbec9, "...m." },
  [8735] = { nil, "Recati ai quattro portali dell'Emerald Dream di Azeroth e raccogli un Fragment of the Nightmare's Corruption da ciascuno. Torna dal Keeper Remulos, a Moonglade, quando avrai completato questo compito.", "Devi recarti ai quattro portali del sogno di Azeroth. Da ciascuno devi estrarre un frammento della corruzione del Nightmare. I draconidi che abitano quelle zone custodiscono tali frammenti. Torna da me quando avrai raccolto questi frammenti.", "<Remulos è immerso nei suoi pensieri.>", "Sei <pronto/pronta>? Il mondo è pronto per ciò che stiamo per invocare? Non lo so... Sono legato dal dovere verso Malfurion. Dovere e onore...", nil, 0x7219c9da, 0x39d38eac, 0x436298cd, 0xbd449033, "m...." },
  [8736] = { "L'incubo si manifesta", "Difendi Nighthaven da Eranikus. Non lasciare che il Keeper Remulos muoia. Non uccidere Eranikus. Difenditi. Attendi Tyrande.", "Dobbiamo usare moderazione contro Eranikus. Dobbiamo redimerlo, non distruggerlo.\n\nTyrande è già in cammino per aiutarci in questo compito. Dobbiamo resistere ai colpi del drago e salvare Nighthaven da una distruzione certa.\n\nState in guardia! Tu e i tuoi alleati siete la nostra unica speranza.", nil, "È redento, {name}. Ora torna nel Dream per rimediare a ciò che lui solo ha sbagliato. Eranikus sarà un potente alleato per Malfurion e per mio padre.\n\nQueste armi sono per te, {name}; me le ha date la stessa Ysera. Faresti bene a usarle nelle tue battaglie contro i Qiraji.", 0xcba14aea, 0x2dd96725, 0xa2b07a01, nil, 0x7383394f, "...m." },
  [8741] = { "Il ritorno del campione", "Porta il Green Scepter Shard ad Anachronos, alle Caverns of Time, a Tanaris.", "Il custode attende il tuo ritorno, {name}. Porta il frammento di scettro verde ad Anachronos, alle Caverns of Time.", nil, nil, 0x0b2dccab, 0x0a07c7ad, 0x23da3e15, nil, nil, "...mm" },
  [8811] = { "Un Commendation Signet", nil, nil, "Agli avventurieri che hanno un solo commendation signet, lo cambierò con un piccolo riconoscimento presso Darnassus.\n\nTieni presente che è meglio consegnare una pila di dieci sigilli in una volta; così i tuoi sforzi riceveranno un riconoscimento maggiore. Offriamo il cambio di un singolo sigillo come servizio per chi non ne ha abbastanza per una pila completa di dieci.\n\nDetto questo, sono a tua disposizione se vuoi comunque consegnare un solo sigillo.", "Molto bene: le tue azioni sono state registrate, e ti viene riconosciuto il merito dei tuoi sforzi. Continua così, {class}.\n\nSe hai altri sigilli da consegnare, posso aiutarti anche con quelli.", 0x34f5a7be, nil, nil, 0xd169c818, 0x3fd3f6f6, ".mm.." },
  [8812] = { "Un Commendation Signet", nil, nil, nil, "Molto bene: le tue azioni sono state registrate, e ti viene riconosciuto il merito dei tuoi sforzi. Continua così, {class}.\n\nSe hai altri sigilli da consegnare, posso aiutarti anche con quelli.", 0x34f5a7be, nil, nil, nil, 0x3fd3f6f6, ".mmm." },
  [8813] = { "Un Commendation Signet", nil, nil, nil, "Molto bene: le tue azioni sono state registrate, e ti viene riconosciuto il merito dei tuoi sforzi. Continua così, {class}.\n\nSe hai altri sigilli da consegnare, posso aiutarti anche con quelli.", 0x34f5a7be, nil, nil, nil, 0x3fd3f6f6, ".mmm." },
  [8814] = { "Un Commendation Signet", nil, nil, "Per gli avventurieri che hanno un solo commendation signet, lo scambierò con un piccolo riconoscimento da parte di Stormwind.\n\nTieni presente che è meglio consegnare dieci sigilli tutti insieme: i tuoi sforzi riceveranno un riconoscimento maggiore. Offriamo lo scambio di un singolo sigillo come servizio per chi non ne ha abbastanza per un gruppo di dieci.\n\nDetto questo, sono a disposizione se vuoi ancora consegnare un singolo sigillo.", "Molto bene: le tue azioni sono state registrate, e ti viene riconosciuto il merito dei tuoi sforzi. Continua così, {class}.\n\nSe hai altri sigilli da consegnare, posso aiutarti anche con quelli.", 0x34f5a7be, nil, nil, 0xac59aabd, 0x3fd3f6f6, ".mm.." },
  [8815] = { "Un Commendation Signet", nil, nil, nil, "Molto bene: le tue azioni sono state registrate, e ti viene riconosciuto il merito dei tuoi sforzi. Continua così, {class}.\n\nSe hai altri sigilli da consegnare, posso aiutarti anche con quelli.", 0x34f5a7be, nil, nil, nil, 0x3fd3f6f6, ".mmm." },
  [8816] = { "Un Commendation Signet", nil, nil, nil, "Molto bene: le tue azioni sono state registrate, e ti viene riconosciuto il merito dei tuoi sforzi. Continua così, {class}.\n\nSe hai altri sigilli da consegnare, posso aiutarti anche con quelli.", 0x34f5a7be, nil, nil, nil, 0x3fd3f6f6, ".mmm." },
  [8817] = { "Un Commendation Signet", nil, nil, nil, "Molto bene: le tue azioni sono state registrate, e ti viene riconosciuto il merito dei tuoi sforzi. Continua così, {class}.\n\nSe hai altri sigilli da consegnare, posso aiutarti anche con quelli.", 0x34f5a7be, nil, nil, nil, 0x3fd3f6f6, ".mmm." },
  [8818] = { "Un Commendation Signet", nil, nil, nil, "Molto bene: le tue azioni sono state registrate, e ti viene riconosciuto il merito dei tuoi sforzi. Continua così, {class}.\n\nSe hai altri sigilli da consegnare, posso aiutarti anche con quelli.", 0x34f5a7be, nil, nil, nil, 0x3fd3f6f6, ".mmm." },
  [8819] = { "Dieci Commendation Signets", nil, nil, "Accetto i commendation signets dagli avventurieri che li hanno ricevuti nell'adempimento del dovere. Per ogni serie di dieci che mi consegni, farò in modo che tu riceva un riconoscimento significativo delle tue azioni presso Darnassus. Accetto anche gettoni singoli, ma con un riconoscimento molto ridotto. Ci interessano molto di più le grandi imprese, anche se nessuna impresa sarà ignorata.\n\nDetto questo, prenderò volentieri i tuoi sigilli se sei <pronto/pronta> a consegnarne una serie.", "Eccellente! Non è un sacrificio da poco quello che hai fatto per guadagnarti questi sigilli, e il tuo servizio sarà riconosciuto come si deve. Sono gli avventurieri come te, {name}, a fare davvero la differenza.\n\nFammi sapere se hai altri sigilli da consegnare; ti aiuterò volentieri con tutti quelli che vuoi cambiare.", 0xc9ab59cb, nil, nil, 0xd21ad71b, 0xd1519e98, ".mm.." },
  [8820] = { "Dieci Commendation Signets", nil, nil, nil, "Eccellente! Non è un sacrificio da poco quello che hai fatto per guadagnarti questi sigilli, e il tuo servizio sarà riconosciuto come si deve. Sono gli avventurieri come te, {name}, a fare davvero la differenza.\n\nFammi sapere se hai altri sigilli da consegnare; ti aiuterò volentieri con tutti quelli che vuoi cambiare.", 0xc9ab59cb, nil, nil, nil, 0xd1519e98, ".mmm." },
  [8821] = { "Dieci Commendation Signets", nil, nil, nil, "Eccellente! Non è un sacrificio da poco quello che hai fatto per guadagnarti questi sigilli, e il tuo servizio sarà riconosciuto come si deve. Sono gli avventurieri come te, {name}, a fare davvero la differenza.\n\nFammi sapere se hai altri sigilli da consegnare; ti aiuterò volentieri con tutti quelli che vuoi cambiare.", 0xc9ab59cb, nil, nil, nil, 0xd1519e98, ".mmm." },
  [8822] = { "Dieci Commendation Signets", nil, nil, "Accetto i commendation signet dagli avventurieri che li hanno ricevuti nell'adempimento del dovere. Per ogni gruppo di dieci che mi consegni, farò in modo che tu riceva un riconoscimento significativo delle tue imprese da parte di Stormwind. Accetto anche sigilli singoli, ma con un riconoscimento molto ridotto. Ci interessano molto di più le grandi imprese, anche se nessuna impresa sarà ignorata.\n\nDetto questo, prenderò volentieri i tuoi sigilli se sei <pronto/pronta> a consegnarne un gruppo.", "Eccellente! Non è un sacrificio da poco quello che hai fatto per guadagnarti questi sigilli, e il tuo servizio sarà riconosciuto come si deve. Sono gli avventurieri come te, {name}, a fare davvero la differenza.\n\nFammi sapere se hai altri sigilli da consegnare; ti aiuterò volentieri con tutti quelli che vuoi cambiare.", 0xc9ab59cb, nil, nil, 0x52d74109, 0xd1519e98, ".mm.." },
