  [8827] = { "I regali di Winter", "Parla con il Greatfather Winter. Si trova vicino all'area dei venditori di Smokywood Pastures, a Ironforge.", "Ho sentito che il Greatfather Winter, con il generoso sostegno di Smokeywood Pastures, ha messo regali per tutti sotto l'albero di Ironforge. Vorrei poterci andare, ma devo badare al PX-238 Winter Wondervolt.\n\nMa tu dovresti proprio andare a vedere. Sono sicuro che il Greatfather Winter ha dei regali con il tuo nome sopra.", nil, "Oh, oh, salve! Puoi essere qui per un solo motivo: aprire i tuoi regali del Winter Veil.\n\nNon preoccuparti, il Greatfather Winter non si è dimenticato di te, {class} della razza {race} a lui tanto cara. Guarda sotto l'albero e troverai i tuoi doni.\n\nIn questa stagione di doni, forse anche ai tuoi amici farebbe piacere ricevere qualcuno degli ottimi prodotti di Smokeywood Pasture?", 0xe0911411, 0x24244a23, 0xd280792a, nil, 0xbcb9cdb9, "...m." },
  [8828] = { "I regali di Winter", nil, nil, nil, nil, 0xe0911411, nil, nil, nil, nil, ".mmmm" },
