  [8841] = { "Dieci Commendation Signets", nil, nil, nil, "Eccellente! Non è un sacrificio da poco quello che hai fatto per guadagnarti questi sigilli, e il tuo servizio sarà riconosciuto come si deve. Sono gli avventurieri come te, {name}, a fare davvero la differenza.\n\nFammi sapere se hai altri sigilli da consegnare; ti aiuterò volentieri con tutti quelli che vuoi cambiare.", 0xc9ab59cb, nil, nil, nil, 0xd1519e98, ".mmm." },
